window.addEventListener("DOMContentLoaded", async () => {
  const loader = document.getElementsByClassName("loader")[0];
  const ResponseData = await fetch("http://localhost:3000/givecard/data").then(
    (response) => response.json()
  );

  if (ResponseData) {
    const labels = ResponseData[0].labels;
    const dataRE = ResponseData[1].data;

    const data = {
      labels,
      datasets: [
        {
          label: "Cards Created",
          backgroundColor: "#02183b",
          borderColor: "#2056ab",
          data: dataRE,
        },
      ],
    };

    const config = {
      type: "line",
      data: data,
      options: {
        animations: {
          radius: {
            duration: 400,
            easing: "linear",
            loop: (context) => context.active,
          },
        },
        hoverRadius: 12,
        responsive: true,
        interaction: {
          mode: "index",
          intersect: false,
        },
      },
    };
    const myChart = new Chart(document.getElementById("lp-34ed2"), config);
  }

  loader.style.display = "none";
});
